window.RP_SESSION={"id":"S-2530cc163392","messages":[{"id":"RP-0202018","time":"2026-07-28T15:25:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 놀랍지 않은 사실 : 사이먼 포레스트는 배교자다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202019","time":"2026-07-28T15:26:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그리고 조금은 더 놀라운 사실. 그것은 누군가의 강요가 없는 스스로의 의지였다. 에노라의 부탁을 거절한 이상, 사이먼에게 변명의 여지란 없다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202020","time":"2026-07-28T15:28:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 무엇이든 처음이 어렵지 그 다음부턴 쉽다.\n 사람을 베는 것이 그랬고 시신을 만지는 것도 그랬다. 그렇다면 배교자인 사이먼이 다시한번 배교를 할 수도 있지 않겠는가?\n 그러니 다시 묻겠건데 희생이시여. 저는 아직 사제입니까? 숭고한 선택을 한 저는 여전히 숭고합니까?","characters":["P-3ea4affc20fd"]},{"id":"RP-0202021","time":"2026-07-28T15:30:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"라고나 할까...","characters":["P-3ea4affc20fd"]},{"id":"RP-0202022","time":"2026-07-28T15:31:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 자신이 오만함을 느끼는 요즘이었다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202023","time":"2026-07-28T15:33:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 내가 뭔데 저들을 구하고자 할까. 내가 뭔데 도움을 권하는 것일까? 나이 서른 넘게 먹고 이런 생각을 하는 자신이 우습기도 하다.\n 내가 뭔데 라운데라님을 배신했지?","characters":["P-3ea4affc20fd"]},{"id":"RP-0202024","time":"2026-07-28T15:34:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"같은 거 말이다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202025","time":"2026-07-28T15:36:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 라운데라님을 믿을 적에는 이런 식의 혼란은 겪지 않았는데!\n 라는 한탄이 어린애 투정 같이 느껴진다. 스스로가 배신했으면서. 여전히 배신한 신에게 의존하려 하는 이기심이.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202026","time":"2026-07-28T15:38:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 신이시여, 저는 어찌해야 합니까.\n 신이시여, 저것은 악합니까?\n 신이시여, 저희를 구원하소서.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202027","time":"2026-07-28T15:39:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"와 진짜-.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202028","time":"2026-07-28T15:40:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 스스로 생각하는 법을 잊어버린 자의 말로다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202029","time":"2026-07-28T15:41:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아니 진짜 나이 서른 넘게 먹고 열세살짜리 마냥...","characters":["P-3ea4affc20fd"]},{"id":"RP-0202030","time":"2026-07-28T15:42:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 하고 싶은 것이 변하지 않아서 다행이다. 뭘 하고 싶은건지 생각해본적 없어서도 있지만","characters":["P-3ea4affc20fd"]},{"id":"RP-0202031","time":"2026-07-28T15:42:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 밥이나 먹어야지.","characters":["P-3ea4affc20fd"]},{"id":"RP-0202032","time":"2026-07-28T15:42:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-0202033","time":"2026-07-28T15:42:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
